-- Explicações por artigo — Lei do Uso de Instrumentos de Menor Potencial Ofensivo (Lei nº 13.060, de 2014). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei disciplina o uso dos instrumentos de menor potencial ofensivo pelos agentes de segurança pública em todo o território nacional.', '["Disciplina o uso dos instrumentos de menor potencial ofensivo.","Aplica-se em todo o território nacional."]'::jsonb, '["Abrangência nacional."]'::jsonb, 'A Lei vale para as polícias de todos os Estados.', '["Assertiva que restringe a Lei à Polícia Federal erra: aplica-se a todos os agentes de segurança pública."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'menor-potencial-ofensivo' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos de segurança pública deverão priorizar a utilização dos instrumentos de menor potencial ofensivo, desde que seu uso não coloque em risco a integridade física ou psíquica dos policiais, e obedecer aos princípios da legalidade, necessidade, razoabilidade e proporcionalidade. Não é legítimo o uso de arma de fogo contra pessoa em fuga desarmada ou que não represente risco imediato de morte ou de lesão aos agentes ou a terceiros, nem contra veículo que desrespeite bloqueio policial em via pública, exceto quando o ato represente risco de morte ou lesão.', '["Priorizar instrumentos de menor potencial ofensivo, sem pôr em risco o policial.","Princípios: legalidade, necessidade, razoabilidade e proporcionalidade.","Vedado atirar em fugitivo desarmado que não ofereça risco imediato.","Vedado atirar contra veículo que fure bloqueio, salvo risco de morte ou lesão."]'::jsonb, '["Veículo que fura bloqueio: arma de fogo só se houver risco de morte ou lesão.","A prioridade não obriga o policial a se expor a risco."]'::jsonb, 'O policial usa dispositivo de choque em vez de arma de fogo ao conter pessoa agressiva que não porta arma.', '["Assertiva que autoriza o disparo contra qualquer veículo que desrespeite o bloqueio erra: exige risco de morte ou lesão."]'::jsonb, '[]'::jsonb, '["Decreto do Uso da Força"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'menor-potencial-ofensivo' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os cursos de formação e capacitação dos agentes de segurança pública deverão incluir conteúdo programático que os habilite ao uso dos instrumentos não letais.', '["Formação e capacitação incluem o uso de instrumentos não letais."]'::jsonb, '["Dever de capacitação nos cursos de formação."]'::jsonb, 'O curso de formação policial inclui treinamento com instrumentos não letais.', '["Assertiva que dispensa o treinamento em instrumentos não letais nos cursos erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'menor-potencial-ofensivo' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Consideram-se instrumentos de menor potencial ofensivo aqueles projetados especificamente para, com baixa probabilidade de causar mortes ou lesões permanentes, conter, debilitar ou incapacitar temporariamente pessoas.', '["Projetados para conter, debilitar ou incapacitar temporariamente.","Baixa probabilidade de causar morte ou lesões permanentes."]'::jsonb, '["Baixa probabilidade, e não ausência, de risco de morte."]'::jsonb, 'Spray de pimenta e arma de choque são instrumentos de menor potencial ofensivo.', '["Assertiva que afirma que esses instrumentos nunca causam morte erra: a definição fala em baixa probabilidade."]'::jsonb, '[{"termo":"Instrumento não letal","significado":"Equipamento concebido para reduzir o risco de morte."}]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'menor-potencial-ofensivo' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

